public void process(METSalesPickingListGenerationContract _dataContract)
{
    Batch                                       currentBatchTask = this.getCurrentBatchTask();
    METSalesPickingListGenerationController     controller;
    METSalesPickingListGenerationContract       contract;

    controller = METSalesPickingListGenerationController::construct(new Args());   
    contract = controller.getDataContractObject();
    contract.parmSalesOrderList(_dataContract.parmSalesOrderList());
    contract.parmCSDSalesOrderList(_dataContract.parmCSDSalesOrderList());
    contract.parmCsdGuid(_dataContract.parmCsdGuid());
    contract.parmContinueFromStagingLane(_dataContract.parmContinueFromStagingLane());
    contract.parmBatchJobId(currentBatchTask.BatchJobId);

    controller.parmShowDialog(false);
    controller.startOperation();
}
